"""Algorithm A -- Berggren descent: address, depth, and reconstruction of a seed."""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Tuple

Seed = Tuple[int, int]


def is_seed(m: int, n: int) -> bool:
    """A Euclid seed: 0 < n < m, coprime, of opposite parity."""
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def child(p: Seed, branch: int) -> Seed:
    """Apply Berggren move 1, 2 or 3 in Euclid-seed coordinates."""
    m, n = p
    if branch == 1:
        return (2 * m - n, m)
    if branch == 2:
        return (2 * m + n, m)
    if branch == 3:
        return (m + 2 * n, n)
    raise ValueError("branch must be 1, 2 or 3")


def parent(p: Seed) -> Optional[Seed]:
    """The unique Berggren parent of a seed, or None at the root (2, 1).

    Which move produced p is a trichotomy in the slope n/m:
        n/m in (1/2, 1)  ->  move 1        (m <= 2n)
        n/m in (1/3, 1/2)->  move 2        (2n < m <= 3n)
        n/m in (0, 1/3)  ->  move 3        (3n < m)
    """
    m, n = p
    if (m, n) == (2, 1):
        return None
    if 3 * n < m:
        return (m - 2 * n, n)
    if 2 * n < m:
        return (n, m - 2 * n)
    return (n, 2 * n - m)


def address(p: Seed) -> List[int]:
    """The unique word in {1,2,3}* leading from the root (2,1) to the seed p.

    Raises ValueError if p is not a Euclid seed.  Termination: each application of
    `parent` strictly decreases the first coordinate, so the loop is finite.
    """
    if not is_seed(*p):
        raise ValueError(f"{p} is not a Euclid seed")
    word: List[int] = []
    q: Seed = p
    while True:
        r = parent(q)
        if r is None:
            break
        for b in (1, 2, 3):
            if child(r, b) == q:
                word.append(b)
                break
        q = r
    return list(reversed(word))


def depth(p: Seed) -> int:
    """The (unique) depth at which the seed p occurs in the Berggren tree."""
    return len(address(p))


def from_address(word: List[int]) -> Seed:
    """Reconstruct the seed at the end of a branch word, starting from the root."""
    p: Seed = (2, 1)
    for b in word:
        p = child(p, b)
    return p


def demo() -> None:
    for p in [(2, 1), (3, 2), (5, 2), (9, 4), (12, 5), (16, 9), (65, 8), (169, 70)]:
        if not is_seed(*p):
            continue
        w = address(p)
        assert from_address(w) == p
        print(f"seed {str(p):>12}  depth {depth(p):>2}  "
              f"address {''.join('B' + str(b) for b in w) or '(root)'}  "
              f"triple {(p[0]**2 - p[1]**2, 2*p[0]*p[1], p[0]**2 + p[1]**2)}")


if __name__ == "__main__":
    demo()

"""Algorithm C -- Factorisation by geodesic collision (Euler's two-representation method).

Nodes of the Berggren tree are enumerated in increasing order of hyperbolic
distance from the base point -- equivalently, of hypotenuse c = m^2 + n^2, since
cosh d = (c+1)/(2m) and d = (1/2) log c + O(1).  As soon as two distinct nodes
share the hypotenuse N, the pair of representations
    N = m1^2 + n1^2 = m2^2 + n2^2
splits N completely:
    gcd(N, m1*m2 + n1*n2) * gcd(N, m1*n2 + n1*m2) = N,   both factors in (1, N).

Complexity.  Correct but not fast.  The hyperbolic ball of radius R contains
about ((pi+2)/(4 pi^2)) e^{2R} nodes, and a collision for N is only guaranteed
inside the ball of radius (1/2) log N -- which already contains ~N nodes.  So the
enumeration is Theta(N) in the worst case: the geometry gives no speed-up.  The
routine below is therefore a demonstration of the *mechanism*, not a competitive
factoring algorithm.
"""

from __future__ import annotations

import math
from math import gcd, isqrt
from typing import Dict, Iterator, List, Optional, Tuple

Seed = Tuple[int, int]


def is_seed(m: int, n: int) -> bool:
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def node_distance(m: int, n: int) -> float:
    return math.acosh((m * m + n * n + 1) / (2 * m))


def nodes_by_distance(c_max: int) -> Iterator[Tuple[float, Seed]]:
    """All Euclid seeds with hypotenuse <= c_max, yielded in increasing distance."""
    out: List[Tuple[float, Seed]] = []
    m_top = isqrt(c_max)
    for m in range(2, m_top + 1):
        for n in range(1, m):
            if m * m + n * n > c_max:
                break
            if is_seed(m, n):
                out.append((node_distance(m, n), (m, n)))
    out.sort()
    return iter(out)


def euler_split(n_target: int, a: Seed, b: Seed) -> Tuple[int, int]:
    """The two gcds produced by a collision; their product is N for odd primitive N."""
    g = gcd(n_target, a[0] * b[0] + a[1] * b[1])
    h = gcd(n_target, a[0] * b[1] + a[1] * b[0])
    return g, h


def factor_by_collision(n_target: int) -> Optional[Tuple[int, int, Seed, Seed, int]]:
    """Search the tree for a collision on N.

    Returns (g, h, seedA, seedB, nodes_inspected) with g*h = N and 1 < g,h < N,
    or None if N is carried by fewer than two nodes (then the method is silent).
    """
    seen: Dict[int, Seed] = {}
    inspected = 0
    for _, (m, n) in nodes_by_distance(n_target):
        inspected += 1
        c = m * m + n * n
        if c != n_target:
            continue
        if c in seen:
            g, h = euler_split(n_target, seen[c], (m, n))
            if 1 < g < n_target and 1 < h < n_target:
                return g, h, seen[c], (m, n), inspected
        else:
            seen[c] = (m, n)
    return None


def search_cost_estimate(n_target: int) -> float:
    """Predicted number of nodes inside the ball guaranteed to contain a collision."""
    r = 0.5 * math.log(n_target)
    return (math.pi + 2) / (4 * math.pi ** 2) * math.exp(2 * r)


def demo() -> None:
    for n_target in (65, 85, 325, 1105, 5525, 32045):
        res = factor_by_collision(n_target)
        est = search_cost_estimate(n_target)
        if res is None:
            print(f"N = {n_target:>7}: no collision -- the method is silent")
            continue
        g, h, a, b, inspected = res
        print(f"N = {n_target:>7} = {g} * {h}   from nodes {a} and {b}   "
              f"nodes inspected {inspected:>6}   predicted ball size {est:>10.1f}")


if __name__ == "__main__":
    demo()
